{"implementation":"def solve(case):
    lines = case.get('lines', [])
    trajectory = []
    error_line = None
    valid = True
    state = 0
    for i, line in enumerate(lines):
        stripped = line.strip()
        if stripped.startswith('Thought:'):
            typ = 'thought'
            content = stripped[len('Thought:'):].strip()
        elif stripped.startswith('Action:'):
            typ = 'action'
            content = stripped[len('Action:'):].strip()
        elif stripped.startswith('Observation:'):
            typ = 'observation'
            content = stripped[len('Observation:'):].strip()
        elif stripped.startswith('Final:'):
            typ = 'final'
            content = stripped[len('Final:'):].strip()
        else:
            error_line = i
            valid = False
            break
        if state == 0:
            if typ != 'thought':
                error_line = i
                valid = False
                break
        elif state == 1:
            if typ not in ('action', 'final'):
                error_line = i
                valid = False
                break
        elif state == 2:
            if typ != 'observation':
                error_line = i
                valid = False
                break
        elif state == 3:
            if typ not in ('thought', 'final'):
                error_line = i
                valid = False
                break
        elif state == 4:
            error_line = i
            valid = False
            break
        if typ == 'thought':
            state = 1
        elif typ == 'action':
            state = 2
        elif typ == 'observation':
            state = 3
        elif typ == 'final':
            state = 4
        trajectory.append({'type': typ, 'content': content})
    else:
        if state != 4:
            valid = False
            if len(lines) > 0:
                error_line = len(lines) - 1
            else:
                error_line = 0
    return {'trajectory': trajectory, 'valid': valid, 'error_line': error_line}"}
